const realtimeToolSchemasJSON = `[{"type":"function","name":"delegate_to_worker","description":"Delegate complex work to the Codex/workspace worker instead of improvising in the realtime voice model. The worker can run shell commands, read/write files, inspect git repos, run tests, execute Python/Node/CLI tools, fetch arbitrary URLs, read links, and perform multi-step debugging/research/planning with fuller context.","parameters":{"type":"object","properties":{"task":{"type":"string","description":"Clear task for the worker, including URLs, file paths, expected output, and any user wording that matters."},"context":{"type":"string","description":"Useful meeting/workspace context. Include Meet chat links or prior tool results when relevant."},"mode":{"type":"string","enum":["analysis","code","research","debug","plan"],"default":"analysis"},"allowCodeChanges":{"type":"boolean","default":false}},"required":["task"]}},{"type":"function","name":"worker_status","description":"Check status/result of a delegated worker job.","parameters":{"type":"object","properties":{"jobId":{"type":"string"}},"required":[]}},{"type":"function","name":"delegate_to_codex","description":"Alias for delegate_to_worker. Use this when the user asks for anything Codex is better at: reading/summarizing links, fetching X/Twitter via Jina or web fetch, downloading videos/files/media when legally accessible, running commands, checking files, reading repos, debugging code, changing code, searching workspace state, writing plans, or doing multi-step research. Do not say you cannot do these tasks; delegate to Codex.","parameters":{"type":"object","properties":{"task":{"type":"string","description":"Clear task for Codex. Include exact URLs/file paths/commands and what to report back."},"context":{"type":"string","description":"Useful meeting/workspace context. Include Meet chat links or prior tool results when relevant."},"mode":{"type":"string","enum":["analysis","code","research","debug","plan"],"default":"analysis"},"allow_code_changes":{"type":"boolean","default":false},"wait_for_result":{"type":"boolean","default":false}},"required":["task"]}},{"type":"function","name":"delegate_status","description":"Legacy alias for worker_status. Check status/result of a delegated Codex worker job.","parameters":{"type":"object","properties":{"job_id":{"type":"string"}},"required":[]}},{"type":"function","name":"send_meet_chat","description":"Send a short visible message into the current Google Meet chat.","parameters":{"type":"object","properties":{"text":{"type":"string","description":"The exact chat message to send to the current Meet."}},"required":["text"]}},{"type":"function","name":"present_video_stage","description":"Open a controlled video/stage tab and make Google Meet share that stage. Use immediately when the user says 放视频 / 分享视频 / 播放视频 / share screen with a video / open video stage / present video. This uses the synthetic screen-share path by default, keeps the Live2D camera separate, and avoids desktop TCC/native picker failures. For non-direct video links, first delegate to Codex to download/resolve a playable file or URL, then call this tool. If Codex returns both a local downloaded video path and a remote direct URL, prefer the local downloaded video path.","parameters":{"type":"object","properties":{"videoUrl":{"type":"string","description":"Direct video URL, data URL, file URL, or local file path. Optional: without it, a placeholder stage is shared."},"title":{"type":"string","description":"Visible title on the shared stage."},"subtitle":{"type":"string","description":"Visible subtitle on the shared stage."},"muted":{"type":"boolean","default":true}},"required":[]}},{"type":"function","name":"stop_video_stage","description":"Stop the current Google Meet video-stage/screen-share presentation. Use immediately when the user says 停止分享 / stop sharing / 关掉分享 / stop video stage.","parameters":{"type":"object","properties":{},"required":[]}},{"type":"function","name":"read_meet_chat","description":"Read recent visible Google Meet chat messages and links from the current meeting.","parameters":{"type":"object","properties":{"limit":{"type":"integer","default":10},"onlyLinks":{"type":"boolean","default":false}},"required":[]}},{"type":"function","name":"fetch_url","description":"Read a public URL and return extracted text/markdown. Uses the Jina reader by default, which is useful for X/Twitter links and pages that are hard to read directly. If this fails or the request needs deeper browsing, delegate to Codex.","parameters":{"type":"object","properties":{"url":{"type":"string","description":"The exact http(s) URL to read."},"useJina":{"type":"boolean","default":true,"description":"Use the Jina reader service instead of direct fetch."},"maxChars":{"type":"integer","default":8000,"description":"Maximum returned text characters."}},"required":["url"]}},{"type":"function","name":"current_user_identity","description":"Return the current meeting speaker/user identity. Use whenever the user asks who they are, says 'my/me/I', or asks for their own workspace data.","parameters":{"type":"object","properties":{},"required":[]}},{"type":"function","name":"search_team_members","description":"Search Linear users/team members and return fuzzy candidates. Use before assignee-specific Linear lookups if the spoken name is ambiguous.","parameters":{"type":"object","properties":{"query":{"type":"string","description":"Name, nickname, email, or spoken partial name."}},"required":["query"]}},{"type":"function","name":"linear_query","description":"Search Linear issues by free text in title/description. Use for issue keyword lookups.","parameters":{"type":"object","properties":{"query":{"type":"string"},"limit":{"type":"integer","default":5}},"required":["query"]}},{"type":"function","name":"linear_user_issues","description":"List incomplete Linear issues assigned to a user. Use for 'my tasks', 'tasks on someone's plate', or assignee questions.","parameters":{"type":"object","properties":{"user":{"type":"string","description":"Email, display name, handle, or username. Prefer the current workspace user's email when available, for example user@example.com."}},"required":["user"]}},{"type":"function","name":"google_calendar","description":"Search Google Calendar events.","parameters":{"type":"object","properties":{"time_min":{"type":"string"},"time_max":{"type":"string"},"max_results":{"type":"integer","default":10}},"required":[]}},{"type":"function","name":"calendar_attendees","description":"Look up the calendar event matching the current Meet URL and return attendees.","parameters":{"type":"object","properties":{"meet_url":{"type":"string","description":"Google Meet URL. Defaults to the current meeting when omitted."}},"required":[]}},{"type":"function","name":"slack_search","description":"Search Cue Slack messages.","parameters":{"type":"object","properties":{"query":{"type":"string"},"count":{"type":"integer","default":5}},"required":["query"]}},{"type":"function","name":"notion_search","description":"Search Cue Notion documents.","parameters":{"type":"object","properties":{"query":{"type":"string"}},"required":["query"]}},{"type":"function","name":"github_search","description":"Search GitHub issues, repos, or code.","parameters":{"type":"object","properties":{"query":{"type":"string"},"kind":{"type":"string","enum":["issues","repos","code"],"default":"issues"}},"required":["query"]}},{"type":"function","name":"memory_write","description":"Write session memory for this meeting avatar.","parameters":{"type":"object","properties":{"key":{"type":"string"},"value":{}},"required":["key"]}},{"type":"function","name":"memory_read","description":"Read session memory. Omit key to return all memory.","parameters":{"type":"object","properties":{"key":{"type":"string"}},"required":[]}},{"type":"function","name":"now","description":"Return the current date/time in Asia/Shanghai.","parameters":{"type":"object","properties":{},"required":[]}},{"type":"function","name":"set_avatar_expression","description":"Set the Live2D avatar's visible mood before or during an answer.","parameters":{"type":"object","properties":{"mood":{"type":"string","enum":["neutral","happy","surprised","thinking","sad","shy"]}},"required":["mood"]}},{"type":"function","name":"set_avatar_action","description":"Trigger a visible Live2D head/body action. Use nod for agreement, shake for disagreement, wave for greetings, think for reasoning, speak while talking, and emphasize for conclusions.","parameters":{"type":"object","properties":{"action":{"type":"string","enum":["idle","nod","shake","wave","think","lean_forward","emphasize","shrug","speak"]},"intensity":{"type":"number","description":"0.2 to 1.2 is the normal visible range."}},"required":["action"]}},{"type":"function","name":"update_avatar_state","description":"Set the avatar mood and action together for the current response.","parameters":{"type":"object","properties":{"mood":{"type":"string","enum":["neutral","happy","surprised","thinking","sad","shy"]},"action":{"type":"string","enum":["idle","nod","shake","wave","think","lean_forward","emphasize","shrug","speak"]},"intensity":{"type":"number","description":"0.2 to 1.2 is the normal visible range."}},"required":[]}}]`

func defaultRealtimeToolSchemas() []map[string]any {
	var tools []map[string]any
	if err := json.Unmarshal([]byte(realtimeToolSchemasJSON), &tools); err != nil {
		return []map[string]any{}
	}
	return tools
}
